import React, { useEffect, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

function UserDashboard({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [votingHistory, setVotingHistory] = useState([]);
  const [electionStatus, setElectionStatus] = useState("loading");
  const [message, setMessage] = useState("");

  useEffect(() => {
    fetchCandidates();
    fetchVotingHistory();
    fetchElectionStatus();
  }, []);

  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  const fetchVotingHistory = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/votes/history`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      setVotingHistory(res.data);
    } catch {
      setMessage("Failed to load voting history.");
    }
  };

  const fetchElectionStatus = async () => {
    try {
      const res = await axios.get(`${API_URL}/admin/status`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      setElectionStatus(res.data.status);
    } catch {
      setElectionStatus("error");
    }
  };

  const handleVote = async (candidateId) => {
    if (electionStatus === "Closed") {
      alert("Election is closed. You cannot vote.");
      return;
    }

    try {
      await axios.post(
        `${API_URL}/api/votes`,
        { candidateId },
        { headers: { Authorization: `Bearer ${auth.token}` } }
      );
      alert("Vote cast successfully!");
      fetchVotingHistory();
      fetchCandidates();
    } catch {
      alert("Vote failed or you have already voted for this position.");
    }
  };

  // Group candidates by position
  const groupedCandidates = candidates.reduce((groups, c) => {
    if (!groups[c.candidacy]) groups[c.candidacy] = [];
    groups[c.candidacy].push(c);
    return groups;
  }, {});

  return (
    <div style={{ padding: 20 }}>
      <h1>User Dashboard</h1>

      {message && <p>{message}</p>}

      <p>
        <strong>Election Status:</strong> {electionStatus}
      </p>

      {/* Voting History */}
      <section>
        <h2>Voting History</h2>
        {votingHistory.length === 0 ? (
          <p>No votes yet.</p>
        ) : (
          <ul>
            {votingHistory.map((v) => (
              <li key={v._id}>
                {v.position}: {v.candidateName}
              </li>
            ))}
          </ul>
        )}
      </section>

      {/* Candidate Summary & Voting */}
      <section>
        <h2>Available Elections & Candidates</h2>
        {Object.entries(groupedCandidates).map(([position, candidates]) => (
          <div key={position} style={{ marginTop: 30 }}>
            <h3 style={{ borderBottom: "2px solid gray", paddingBottom: 5 }}>
              {position}
            </h3>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 20 }}>
              {candidates.map((candidate) => (
                <div
                  key={candidate._id}
                  style={{
                    padding: 15,
                    borderRadius: 10,
                    width: 250,
                    backgroundColor: "#fff",
                    boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
                  }}
                >
                  {candidate.image && (
                    <img
                      src={`${API_URL}/uploads/${candidate.image}`}
                      alt="candidate"
                      style={{
                        width: "100%",
                        height: 180,
                        objectFit: "cover",
                        borderRadius: 8,
                      }}
                    />
                  )}

                  <h4 style={{ marginTop: 10 }}>
                    {candidate.firstName} {candidate.lastName}
                  </h4>
                  <p style={{ fontSize: 13, opacity: 0.8 }}>
                    {candidate.yearLevel} - {candidate.block}
                  </p>
                  <p style={{ fontSize: 14, marginTop: 8 }}>
                    {candidate.description || "No platform provided."}
                  </p>

                  <button
                    onClick={() => {
                      if (
                        window.confirm(
                          `Are you sure you want to vote for ${candidate.firstName} ${candidate.lastName}?`
                        )
                      )
                        handleVote(candidate._id);
                    }}
                    style={{
                      marginTop: 12,
                      padding: "8px 16px",
                      backgroundColor: "#6366f1",
                      color: "white",
                      border: "none",
                      borderRadius: 5,
                      cursor: "pointer",
                      width: "100%",
                    }}
                  >
                    Vote
                  </button>
                </div>
              ))}
            </div>
          </div>
        ))}
      </section>
    </div>
  );
}

export default UserDashboard;
